using units "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" {Slot};
import "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" read;
import "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" cell;
import "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" acquire;
import "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" release;
array OneSlot[Slot]::i64;
data Single { available::bool; payload::ref<OneSlot>; }
function create_single(arena::region)::Single { deref(alloc arena Single(false, alloc arena OneSlot(1u64, 5))) }
function read(pool::Single, slot::Slot)::i64 { deref(pool.payload)[slot] }
function cell(pool::Single, slot::Slot)::ref<i64> { ref_at(pool.payload, slot) }
function acquire(pool::Single, value::i64)::Slot {
  if (pool.available) { setfield(pool, available, false); store(pool.payload, Slot(0u32), value); Slot(0u32) }
  else { Slot(1u32) }
}
function release(pool::Single, slot::Slot)::void { setfield(pool, available, true); {} }
export Single; export create_single; export read; export cell; export acquire; export release;

