sources.copy.cod:
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" SlotStore;
using units "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" {Slot};
function copy_into(destination::SlotStore, to::Slot, source::SlotStore, from::Slot)::ref<i64> {
 let target = cell(destination, to);
 store(target, read(source, from));
 target
}
function copy_keep_source(destination::SlotStore, to::Slot, source::SlotStore, from::Slot)::ref<i64> {
 copy_into(destination, to, source, from);
 cell(source, from)
}
export copy_into; export copy_keep_source;

