using symbol "std:io" @print;
using symbol "std:io" @assert;
using units "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" {Slot};
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" SlotStore;
using "integration.cod" Pool;
using "integration.cod" Single;
using "integration.cod" copy_into;
using "integration.cod" copy_keep_source;
symbol @source::region, @destination::region, @scratch::region;
effect @source <- region(4096u64);
effect @destination <- region(4096u64);
proc transient_destination(source::SlotStore)::ref<i64> {
 effect @scratch <- region(4096u64);
 let destination = create_single(@scratch);
 copy_keep_source(destination, Slot(0u32), source, Slot(1u32))
}
{
 let pool = create(@source, 2u32);
 acquire(pool, 7);
 acquire(pool, 11);
 let single = create_single(@destination);
 let source_bytes = used_bytes(@source);
 let destination_bytes = used_bytes(@destination);
 let first = copy_into(single, Slot(0u32), pool, Slot(1u32));
 behave @print(deref(first));
 store(first, 31);
 behave @print(read(single, Slot(0u32)));
 behave @print(read(pool, Slot(1u32)));
 let second = copy_into(pool, Slot(0u32), single, Slot(0u32));
 behave @print(deref(second));
 store(second, 41);
 behave @print(read(pool, Slot(0u32)));
 behave @print(read(single, Slot(0u32)));
 let source_view = transient_destination(pool);
 store(source_view, 61);
 behave @print(read(pool, Slot(1u32)));
 behave @print(read(single, Slot(0u32)));
 behave @assert(used_bytes(@source) == source_bytes);
 behave @assert(used_bytes(@destination) == destination_bytes);
};

